#include <string>
#include <unordered_set>
using namespace std;

class Solution {
public:
    int maxDistinctStartSubstrings(string s) {
        unordered_set<char> seen(s.begin(), s.end());
        return seen.size();
    }
};

import java.util.*;

class Solution {
    public int maxDistinctStartSubstrings(String s) {
        Set<Character> seen = new HashSet<>();
        for (char c : s.toCharArray()) seen.add(c);
        return seen.size();
    }
}

var maxDistinctStartSubstrings = function(s) {
    return new Set(s).size;
